<?php
require __DIR__.'/../includes/bootstrap.php';
$path=parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH)?:'/';
try{switch($path){
case '/':$rows=db()->query('SELECT t.*,u.username,(SELECT COUNT(*) FROM answers a WHERE a.thread_id=t.id) n FROM threads t JOIN users u ON u.id=t.user_id ORDER BY t.created_at DESC LIMIT 100')->fetchAll();$b='<p><a href="/new">ตั้งกระทู้</a></p>';foreach($rows as $r)$b.='<article><h2><a href="/thread?id='.(int)$r['id'].'">'.e($r['title']).'</a></h2><p>'.e($r['username']).' · '.e($r['created_at']).' · '.(int)$r['n'].' คำตอบ</p><p>'.e(mb_substr($r['body'],0,240)).'</p></article>';page('เว็บบอร์ด',$b);break;
case '/register':if($_SERVER['REQUEST_METHOD']==='POST'){post();$n=trim((string)($_POST['username']??''));$pw=(string)($_POST['password']??'');if(!preg_match('/^[A-Za-z0-9_]{3,32}$/',$n)||strlen($pw)<12||strlen($pw)>200)fail('ชื่อ 3–32 ตัว; รหัสผ่านอย่างน้อย 12 ตัว');try{$s=db()->prepare('INSERT INTO users(username,password_hash) VALUES(?,?)');$s->execute([$n,password_hash($pw,PASSWORD_ARGON2ID)]);}catch(Throwable $e){fail('สมัครไม่สำเร็จ');}header('Location:/login',true,303);exit;}page('สมัครสมาชิก','<form method="post">'.token().'<label>ชื่อผู้ใช้<input name="username" required maxlength="32"></label><label>รหัสผ่าน<input name="password" type="password" minlength="12" required></label><button>สมัคร</button></form>');break;
case '/login':if($_SERVER['REQUEST_METHOD']==='POST'){post();$name=trim((string)($_POST['username']??''));$secret=envv('APP_SECRET');if(strlen($secret)<32)fail('ตั้งค่า APP_SECRET ก่อนใช้งาน',500);$ip=hash_hmac('sha256',(string)($_SERVER['REMOTE_ADDR']??''),$secret);$nh=hash_hmac('sha256',strtolower($name),$secret);$s=db()->prepare('SELECT COUNT(*) FROM login_attempts WHERE (ip_hash=? OR username_hash=?) AND attempted_at>NOW()-INTERVAL 15 MINUTE');$s->execute([$ip,$nh]);if((int)$s->fetchColumn()>=10)fail('ลองใหม่ภายหลัง',429);$s=db()->prepare('INSERT INTO login_attempts(ip_hash,username_hash) VALUES(?,?)');$s->execute([$ip,$nh]);$s=db()->prepare('SELECT * FROM users WHERE username=?');$s->execute([$name]);$u=$s->fetch();if(!$u||!password_verify((string)($_POST['password']??''),$u['password_hash']))fail('ชื่อผู้ใช้หรือรหัสผ่านไม่ถูกต้อง',401);session_regenerate_id(true);$_SESSION['uid']=(int)$u['id'];$_SESSION['uname']=$u['username'];$_SESSION['role']=$u['role'];header('Location:/',true,303);exit;}page('ล็อกอิน','<form method="post">'.token().'<label>ชื่อผู้ใช้<input name="username" required></label><label>รหัสผ่าน<input name="password" type="password" required></label><button>เข้าสู่ระบบ</button></form>');break;
case '/logout':post();$_SESSION=[];session_destroy();header('Location:/',true,303);exit;
case '/new':login_required();if($_SERVER['REQUEST_METHOD']==='POST'){post();$title=trim((string)($_POST['title']??''));$body=trim((string)($_POST['body']??''));if($title===''||mb_strlen($title)>160||$body===''||mb_strlen($body)>10000)fail('ข้อมูลไม่ถูกต้อง');$img=save_image();$s=db()->prepare('INSERT INTO threads(user_id,title,body,image_name) VALUES(?,?,?,?)');$s->execute([user()['id'],$title,$body,$img]);header('Location:/thread?id='.db()->lastInsertId(),true,303);exit;}page('ตั้งกระทู้','<form method="post" enctype="multipart/form-data">'.token().fields().'<button>โพสต์</button></form>');break;
case '/thread':$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT t.*,u.username FROM threads t JOIN users u ON u.id=t.user_id WHERE t.id=?');$s->execute([$id]);$t=$s->fetch();if(!$t)fail('ไม่พบกระทู้',404);$b='<article><h2>'.e($t['title']).'</h2><p>'.e($t['username']).' · '.e($t['created_at']).'</p><p>'.nl2br(e($t['body'])).'</p>'.image_tag($t['image_name']).actions('thread',$t).'</article>';if(user())$b.='<form method="post" action="/answer" enctype="multipart/form-data">'.token().'<input type="hidden" name="thread_id" value="'.$id.'">'.fields().'<button>ตอบ</button></form>';else $b.='<a href="/login">ล็อกอินเพื่อตอบ</a>';$s=db()->prepare('SELECT a.*,u.username FROM answers a JOIN users u ON u.id=a.user_id WHERE a.thread_id=? ORDER BY a.created_at');$s->execute([$id]);foreach($s as $a)$b.='<article><h3>'.e($a['title']).'</h3><p>'.e($a['username']).' · '.e($a['created_at']).'</p><p>'.nl2br(e($a['body'])).'</p>'.image_tag($a['image_name']).actions('answer',$a).'</article>';page($t['title'],$b);break;
case '/answer':login_required();post();$tid=(int)($_POST['thread_id']??0);$title=trim((string)($_POST['title']??''));$body=trim((string)($_POST['body']??''));if($title===''||mb_strlen($title)>160||$body===''||mb_strlen($body)>10000)fail('ข้อมูลไม่ถูกต้อง');$img=save_image();$s=db()->prepare('INSERT INTO answers(thread_id,user_id,title,body,image_name) VALUES(?,?,?,?,?)');$s->execute([$tid,user()['id'],$title,$body,$img]);header('Location:/thread?id='.$tid,true,303);exit;
case '/edit':login_required();$type=($_GET['type']??'')==='answer'?'answer':'thread';$table=$type==='answer'?'answers':'threads';$id=(int)($_GET['id']??0);if(!allowed($table,$id))fail('ไม่มีสิทธิ์หรือไม่พบรายการ',403);$s=db()->prepare("SELECT * FROM $table WHERE id=?");$s->execute([$id]);$r=$s->fetch();if($_SERVER['REQUEST_METHOD']==='POST'){post();if(!allowed($table,$id))fail('ไม่มีสิทธิ์',403);$title=trim((string)($_POST['title']??''));$body=trim((string)($_POST['body']??''));if($title===''||mb_strlen($title)>160||$body===''||mb_strlen($body)>10000)fail('ข้อมูลไม่ถูกต้อง');$img=save_image($r['image_name']);$s=db()->prepare("UPDATE $table SET title=?,body=?,image_name=? WHERE id=?");$s->execute([$title,$body,$img,$id]);header('Location:/thread?id='.(int)($r['thread_id']??$id),true,303);exit;}page('แก้ไข','<form method="post" enctype="multipart/form-data">'.token().fields($r['title'],$r['body']).'<button>บันทึก</button></form>');break;
case '/delete':login_required();post();$type=($_POST['type']??'')==='answer'?'answer':'thread';$table=$type==='answer'?'answers':'threads';$id=(int)($_POST['id']??0);if(!allowed($table,$id))fail('ไม่มีสิทธิ์หรือไม่พบรายการ',403);$s=db()->prepare("SELECT image_name,thread_id FROM $table WHERE id=?");$s->execute([$id]);$r=$s->fetch();if($type==='thread'){$q=db()->prepare('SELECT image_name FROM answers WHERE thread_id=?');$q->execute([$id]);foreach($q as $a)remove_image($a['image_name']);}$s=db()->prepare("DELETE FROM $table WHERE id=?");$s->execute([$id]);remove_image($r['image_name']);header('Location:/thread?id='.(int)($r['thread_id']??$id),true,303);exit;
case '/image':$n=(string)($_GET['name']??'');if(!preg_match('/^[a-f0-9]{32}\.(jpg|png|gif)$/',$n))fail('ไม่พบไฟล์',404);$file=UPLOAD_DIR.'/'.$n;if(!is_file($file))fail('ไม่พบไฟล์',404);header('Content-Type:'.(['jpg'=>'image/jpeg','png'=>'image/png','gif'=>'image/gif'][pathinfo($n,PATHINFO_EXTENSION)]));header('X-Content-Type-Options:nosniff');readfile($file);exit;
case '/style.css':header('Content-Type:text/css; charset=utf-8');echo 'body{font:16px system-ui;max-width:850px;margin:auto;padding:1rem;background:#f5f6f8;color:#222}header,article,form{background:white;padding:1rem;margin:1rem 0;border-radius:8px}label{display:block;margin:.8rem 0}input,textarea{box-sizing:border-box;display:block;width:100%;padding:.6rem}textarea{min-height:120px}button{padding:.6rem}.inline{display:inline;padding:0}.photo{max-width:100%;max-height:480px}';exit;
default:fail('ไม่พบหน้า',404);
}}catch(RuntimeException $e){fail($e->getMessage());}catch(Throwable $e){error_log((string)$e);fail('ระบบขัดข้อง กรุณาลองใหม่',500);}
function image_tag(?string $n):string{return $n?'<p><img class="photo" src="/image?name='.e($n).'" alt="รูปแนบ"></p>':'';}
